/**
 * ───────────────────────────────────────────────────────────────────────────────
 * [shadcn registry item · 教学演示件] AI 建议操作 Chips AI Suggestion Chips
 *
 * 来源:uiux-atlas src/content/entries/components/ai-suggestion-chips/demo/Demo.tsx
 *       (由 scripts/generate-registry.mjs 内联生成;源文件保持不动,重跑生成器即刷新)
 *
 * 诚实标注:这是教学演示件,不是生产组件。原 demo 依赖的三个 @/ 内部模块
 * (@/lib/store 参数 store、@/lib/types 类型、@/components/DemoStage 演示舞台)
 * 在 registry 消费端不可用,已原位改写为「[registry 改写]」注释;文件体内对应的
 * getEntryStore / EntrySchema / DemoStage 引用需按各注释提示替换后,本文件才可编译运行。
 * 它记录的是「本站条目页如何实时驱动参数」,供阅读与改写,不可直接安装即用。
 *
 * 依赖:仅 react(+宿主的 react-dom 渲染);registry item 的 dependencies 留空,
 * 由消费端项目按自身版本声明 react。
 * ───────────────────────────────────────────────────────────────────────────────
 */
import { useEffect, useMemo, useRef, useState } from "react";
// [registry 改写] 原:import { getEntryStore } from "@/lib/store"; —— 本站内部参数 store(getEntryStore,演示页参数面板 → 舞台的实时数据源),registry 消费端不可用;接入时请改为本地受控 state(useState + props),文件体内的 getEntryStore / store.get / store.subscribe 调用需同步替换。
// [registry 改写] 原:import type { EntrySchema } from "@/lib/types"; —— 本站条目 schema 的 TS 类型(EntrySchema),registry 消费端不可用;接入时请以你自己的参数定义类型内联替代,文件体内的 EntrySchema 注解需同步替换。
// [registry 改写] 原:import DemoStage from "@/components/DemoStage"; —— 本站演示舞台组件(.demo-stage:cssVar 注入点 + 舞台铭牌 + #s= 分享参数恢复),registry 消费端不可用;接入时请以自有舞台容器(如一个 <div>)替代,文件体内的 <DemoStage> 标签需同步替换。

interface DemoProps {
  entryId: string;
  schema: EntrySchema;
}

/* 建议数据:4 条供 maxChips=3 裁量(第 4 条落横向滚动区),1 条超长供截断演示 */
const SUGGESTIONS = [
  { zh: "对比两级节流的取舍", en: "Compare the two-level throttle trade-offs" },
  { zh: "给锁底滚动写验收要点", en: "Write acceptance criteria for sticky-bottom" },
  { zh: "未闭合语法自愈是怎么实现的", en: "How does unclosed-syntax healing work?" },
  { zh: "生成式 UI 的白名单边界在哪", en: "Where is generative UI's allowlist boundary?" },
];

const ANSWER = "回答已送达 Answer delivered(流式期间建议牌面静止,ready 后才换牌)。";

type TurnPhase = "streaming" | "ready";
type ChipState = "idle" | "sent";

const css = `
.sgc-wrap { width: min(560px, calc(100% - 24px)); position: relative; }
.sgc-feed {
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg-elev);
  padding: 12px 16px;
  display: grid;
  gap: 8px;
}
.sgc-msg { margin: 0; font-size: 13px; line-height: 1.7; color: var(--text-1); }
.sgc-msg.ai { color: var(--text-dim, var(--text-1)); }
.sgc-msg.user {
  justify-self: end;
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  border-radius: 10px;
  padding: 4px 10px;
  max-width: 80%;
}
.sgc-sent-mark { color: var(--accent); font-size: 11px; margin-left: 6px; }
/* chips 行:官方 Suggestions = 横向 ScrollArea(可拖动滚动条) */
.sgc-row {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  scrollbar-width: thin;
  padding: 2px 2px 6px;
  scroll-snap-type: x proximity;
}
.sgc-chip {
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-elev);
  color: var(--text-1);
  font: inherit;
  font-size: 12.5px;
  padding: 5px 14px;
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 30ch;
  scroll-snap-align: start;
  flex: none;
}
.sgc-chip:hover:not([aria-disabled="true"]) { border-color: var(--accent); color: var(--accent); }
.sgc-chip:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
/* 已发送态:✓ 徽标 + 禁用(状态不只靠颜色承载) */
.sgc-chip[aria-disabled="true"] {
  border-style: dashed;
  color: var(--text-faint);
  cursor: default;
  pointer-events: none;
}
.sgc-chip[aria-disabled="true"]:not([data-sent="true"]) { opacity: 0.55; }
.sgc-chip[data-flicker="true"] { animation: sgc-flick 0.35s steps(2) infinite; }
@keyframes sgc-flick { 50% { opacity: 0.4; } }
/* fill-composer 档的输入框中间态(自改写,非官方) */
.sgc-composer {
  display: flex;
  gap: 8px;
  align-items: center;
}
.sgc-composer input {
  flex: 1;
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--bg);
  color: var(--text-1);
  font: inherit;
  font-size: 12.5px;
  padding: 6px 10px;
}
.sgc-composer input:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.sgc-send {
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-elev);
  color: var(--text-1);
  font: inherit;
  font-size: 12px;
  padding: 5px 14px;
  cursor: pointer;
}
.sgc-send:hover:not(:disabled) { border-color: var(--accent); color: var(--accent); }
.sgc-send:disabled { opacity: 0.45; cursor: default; }
.sgc-send:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.sgc-status { margin: 8px 2px 0; font-size: 12px; color: var(--text-faint); }
.sgc-tools { position: absolute; right: -4px; top: -38px; display: flex; gap: 6px; }
.sgc-tools button {
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-elev);
  color: var(--text-1);
  font: inherit;
  font-size: 12px;
  padding: 4px 12px;
  cursor: pointer;
}
.sgc-tools button:hover { border-color: var(--accent); color: var(--accent); }
.sgc-tools button:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.sgc-hint { margin: 8px 2px 0; font-size: 12px; color: var(--text-faint); }
@media (prefers-reduced-motion: reduce) {
  .sgc-chip[data-flicker="true"] { animation: none; opacity: 0.6; }
}
`;

/**
 * AI 建议操作 chips 演示:模拟一轮「流式回答 → ready 换牌 → 点击 → 后态」。
 * maxChips / chipMaxLength / updatePolicy / onClickBehavior / postClickState / scrollDirection
 * 全部为 JS 型参数(订阅 store);无 CSS 变量型参数。
 * live-stream 档为教学反面教材(流中逐 token 抖动换牌),生产默认 ready-gated。
 */
export default function Demo({ entryId, schema }: DemoProps) {
  const store = getEntryStore(entryId, schema);
  const [maxChips, setMaxChips] = useState(() => store.get("maxChips") as number);
  const [chipMaxLength, setChipMaxLength] = useState(() => store.get("chipMaxLength") as number);
  const [updatePolicy, setUpdatePolicy] = useState(() => store.get("updatePolicy") as string);
  const [clickBehavior, setClickBehavior] = useState(() => store.get("onClickBehavior") as string);
  const [postClick, setPostClick] = useState(() => store.get("postClickState") as string);
  const [scrollDirection, setScrollDirection] = useState(() => store.get("scrollDirection") as string);

  const [runId, setRunId] = useState(0);
  const [phase, setPhase] = useState<TurnPhase>("streaming");
  const [streamTick, setStreamTick] = useState(0);
  const [sent, setSent] = useState<string | null>(null);
  const [groupLocked, setGroupLocked] = useState(false);
  const [composerText, setComposerText] = useState("");
  const [userMsgs, setUserMsgs] = useState<string[]>([]);
  const rowRef = useRef<HTMLDivElement>(null);

  useEffect(
    () =>
      store.subscribe(() => {
        setMaxChips(store.get("maxChips") as number);
        setChipMaxLength(store.get("chipMaxLength") as number);
        setUpdatePolicy(store.get("updatePolicy") as string);
        setClickBehavior(store.get("onClickBehavior") as string);
        setPostClick(store.get("postClickState") as string);
        setScrollDirection(store.get("scrollDirection") as string);
      }),
    [store],
  );

  const replay = () => {
    setRunId((n) => n + 1);
    setPhase("streaming");
    setStreamTick(0);
    setSent(null);
    setGroupLocked(false);
    setComposerText("");
    setUserMsgs([]);
  };

  // 模拟回答流:ready-gated 档流中牌面完全静止,live-stream 档牌面逐 tick 抖动换序(反面教材)
  useEffect(() => {
    if (phase !== "streaming") return;
    const id = window.setInterval(() => setStreamTick((t) => t + 1), 180);
    const done = window.setTimeout(() => setPhase("ready"), 2200);
    return () => {
      window.clearInterval(id);
      window.clearTimeout(done);
    };
  }, [runId, phase]);

  const clip = (s: { zh: string; en: string }) => {
    const full = `${s.zh} ${s.en}`;
    return full.length > chipMaxLength ? `${full.slice(0, Math.max(4, chipMaxLength - 1))}…` : full;
  };

  // 轮次边界换牌:ready 后才决定展示哪几条;live-stream 档在流中就随 tick 换序(演示抖动)
  const order = useMemo(() => {
    const seed = updatePolicy === "live-stream" && phase === "streaming" ? streamTick : runId;
    return SUGGESTIONS.map((_, i) => SUGGESTIONS[(i + seed) % SUGGESTIONS.length]);
  }, [updatePolicy, phase, streamTick, runId]);

  const visible = order.slice(0, maxChips);
  const hidden = order.length - visible.length;
  const locked = groupLocked || (postClick !== "hide" && sent !== null && postClick === "disable");

  const sendSuggestion = (text: string) => {
    if (clickBehavior === "fill-composer") {
      setComposerText(text);
      return;
    }
    setUserMsgs((m) => [...m, text]);
    setSent(text);
    setGroupLocked(true);
  };

  const sendComposer = () => {
    if (!composerText.trim()) return;
    setUserMsgs((m) => [...m, composerText]);
    setSent(composerText);
    setComposerText("");
    setGroupLocked(true);
  };

  const chipState = (text: string): ChipState => (sent === text ? "sent" : "idle");

  return (
    <DemoStage entryId={entryId} schema={schema}>
      <div className="sgc-wrap">
        <div className="sgc-tools" role="group" aria-label="演示控制 Demo controls">
          <button type="button" onClick={replay}>重播 Replay</button>
        </div>
        <div className="sgc-feed" aria-live="polite">
          <p className="sgc-msg ai">{phase === "streaming" ? "回答流式生成中 Streaming…" : ANSWER}</p>
          {userMsgs.map((m, i) => (
            <p className="sgc-msg user" key={`${i}-${m.slice(0, 6)}`}>
              {m}
              <span className="sgc-sent-mark">已发送 sent ✓</span>
            </p>
          ))}
        </div>
        <div
          ref={rowRef}
          className="sgc-row"
          role="group"
          aria-label="建议追问 Suggested follow-ups"
          style={scrollDirection === "wrap" ? { flexWrap: "wrap", overflowX: "visible" } : undefined}
        >
          {phase === "ready" || updatePolicy === "live-stream"
            ? visible.map((s) => {
                const text = clip(s);
                const st = chipState(text);
                return (
                  <button
                    type="button"
                    key={text}
                    className="sgc-chip"
                    data-sent={st === "sent" ? "true" : undefined}
                    data-flicker={updatePolicy === "live-stream" && phase === "streaming" ? "true" : undefined}
                    aria-disabled={locked || st === "sent" ? "true" : undefined}
                    title={text}
                    aria-label={text}
                    onClick={() => sendSuggestion(text)}
                  >
                    {text}
                    {st === "sent" ? " ✓" : ""}
                  </button>
                );
              })
            : null}
          {phase === "ready" && hidden > 0 && (
            <span className="sgc-status" style={{ alignSelf: "center", margin: 0 }}>
              +{hidden} 条在滚动区 in scroll area
            </span>
          )}
        </div>
        <div className="sgc-composer">
          <input
            type="text"
            value={composerText}
            placeholder={clickBehavior === "fill-composer" ? "建议填入后可编辑 editable fill…" : "输入消息 Type a message…"}
            aria-label="输入框 Composer"
            onChange={(e) => setComposerText(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") sendComposer();
            }}
          />
          <button type="button" className="sgc-send" onClick={sendComposer} disabled={!composerText.trim()}>
            发送 Send
          </button>
        </div>
        <p className="sgc-status" aria-live="polite">
          {phase === "streaming"
            ? updatePolicy === "ready-gated"
              ? "流式中 · 牌面静止(ready-gated)Streaming — row frozen (ready-gated)"
              : "流式中 · 牌面逐 tick 抖动(live-stream 反面教材)Streaming — row jitters per tick (live-stream anti-pattern)"
            : sent
              ? `已按「${postClick}」处理点击后态 Post-click state: ${postClick}`
              : `就绪 ready · 展示 ${visible.length}/${SUGGESTIONS.length} 条(上限 ${maxChips})Ready · showing ${visible.length}/${SUGGESTIONS.length} (cap ${maxChips})`}
        </p>
        <p className="sgc-hint">
          点一条建议 → 点击即发送(官方用法);fill-composer 档先填输入框 · Click a chip → it sends immediately (official usage); fill-composer fills the composer first
        </p>
      </div>
      <style>{css}</style>
    </DemoStage>
  );
}
